<script setup>
import {computed,ref,watch} from 'vue'
import {cspPresets,backtrackingSteps,validateCsp} from '../services/csp-search.mjs'
import SimulationControls from './SimulationControls.vue'
import SearchTraceCode from './SearchTraceCode.vue'
import CspStateView from './CspStateView.vue'
const props=defineProps({preset:{type:String,default:'australia'}})
const preset=ref(props.preset),problem=ref(cspPresets[props.preset].create()),filtering=ref('mac'),variableOrder=ref('mrv'),valueOrder=ref('lcv'),step=ref(0),input=ref(JSON.stringify(problem.value,null,2)),error=ref('')
const trace=computed(()=>Array.from(backtrackingSteps(problem.value,{filtering:filtering.value,variableOrder:variableOrder.value,valueOrder:valueOrder.value,budget:1000}))),state=computed(()=>trace.value[Math.min(step.value,trace.value.length-1)]),key=computed(()=>JSON.stringify([problem.value,filtering.value,variableOrder.value,valueOrder.value]))
watch(key,()=>step.value=0);watch(preset,()=>{problem.value=cspPresets[preset.value].create();input.value=JSON.stringify(problem.value,null,2);error.value=''})
const message=computed(()=>{const s=state.value;if(s.phase==='success')return 'Tìm được phép gán đầy đủ thỏa mãn mọi ràng buộc.';if(s.phase==='failure')return 'Đã vét hết các nhánh khả dĩ mà không có nghiệm. Với dữ liệu hữu hạn này, CSP vô nghiệm.';if(s.phase==='budget')return 'Hết giới hạn 1000 lần thử gán. Kết quả chưa xác định, không được kết luận vô nghiệm.';if(s.phase==='choose')return `Chọn biến ${s.variable}. Giá trị hợp lệ theo thứ tự thử: ${s.values.join(', ')||'Không còn giá trị'}.`;if(s.phase==='assign')return `Thử gán ${s.variable} = ${s.value}. Kiểm tra trước khi đi sâu.`;if(s.phase==='backtrack')return `Bỏ gán ${s.variable} = ${s.value}. Đã khôi phục đầy đủ các miền trước nhánh này.`;if(s.phase==='filter')return `Kiểm tra tiến từ ${s.source}: Xóa ${s.removed.join(', ')||'không có giá trị nào'} khỏi miền ${s.variable}.`;if(s.phase==='wipeout')return `Miền ${s.variable} rỗng. Nhánh hiện tại không thể mở rộng thành nghiệm.`;if(s.phase==='propagate'){const t=s.propagation;if(t.arc)return `AC-3 xét ${t.arc.join(' → ')}. ${t.phase==='revise'?'Chỉ xóa ở biến đầu: '+(t.removed.join(', ')||'không xóa')+'.':t.phase==='failure'?'Phát hiện miền rỗng.':'Cập nhật thông tin hỗ trợ.'}`;return t.phase==='consistent'?'AC-3 không còn cung cần xét. Tiếp tục tìm kiếm, chưa kết luận có nghiệm.':'Khởi tạo lan truyền trên các miền hiện tại.'}return 'Khởi tạo phép gán rỗng. Bảng miền và đồ thị sẽ cập nhật từ cùng bộ giải.'})
function apply(){try{const p=validateCsp(JSON.parse(input.value));Array.from(backtrackingSteps(p,{budget:1000}));problem.value=p;error.value=''}catch(e){error.value=e.message}}
</script>
<template><section class="math-lab csp-search" aria-label="Mô phỏng tìm kiếm quay lui CSP"><div class="csp-settings"><label>Bài toán<select v-model="preset"><option v-for="(p,id) in cspPresets" :key="id" :value="id">{{ p.title }}</option></select></label><label>Lọc miền<select v-model="filtering"><option value="none">Quay lui, không lọc</option><option value="fc">Kiểm tra tiến FC</option><option value="mac">MAC với AC-3</option></select></label><label>Chọn biến<select v-model="variableOrder"><option value="fixed">Thứ tự khai báo</option><option value="mrv">MRV, phá hòa theo bậc</option></select></label><label>Chọn giá trị<select v-model="valueOrder"><option value="fixed">Thứ tự miền ban đầu</option><option value="lcv">LCV</option></select></label></div><SimulationControls v-model="step" :max="trace.length-1" :reset-key="key"/><CspStateView :problem="problem" :state="state"/><div class="csp-stats"><span>Độ sâu {{ state.depth }}</span><span>Thử gán {{ state.attempts }}</span><span>Xóa giá trị {{ state.prunes }}</span><span>REVISE {{ state.revisions }}</span></div><p class="csp-status" role="status">{{ message }}</p><div v-if="state.propagation?.queue.length" class="csp-queue"><h4>Hàng đợi cung, đầu ở bên trái</h4><span v-for="([a,b],i) in state.propagation.queue" :key="i">{{ a }} → {{ b }}</span></div><details><summary>Ngăn xếp phép gán và quy tắc chọn</summary><ol><li v-for="([v,x]) in Object.entries(state.assignment)" :key="v">{{ v }} = {{ x }}</li></ol><p v-if="!state.depth">Ngăn xếp rỗng.</p><div v-if="state.choices" class="choice-list"><p v-for="c in state.choices" :key="c.variable">{{ c.variable }}: {{ c.remaining }} giá trị hợp lệ, {{ c.degree }} láng giềng chưa gán.</p></div><p>MRV đếm giá trị hợp lệ hiện tại. Phá hòa bằng số biến chưa gán kề lớn nhất rồi thứ tự khai báo. LCV đếm số giá trị hợp lệ của các láng giềng chưa gán bị loại trực tiếp. Khi hòa, giữ thứ tự miền ban đầu.</p><p>Thử gán, số giá trị bị xóa và số lần REVISE là ba phép đếm khác nhau. Chúng chưa đo toàn bộ thời gian chạy. Đổi lựa chọn sẽ đặt lại truy vết.</p></details><details class="csp-input"><summary>Tự nhập CSP nhị phân</summary><p>variables là danh sách tên biến, domains chứa các miền và constraints chứa a, b, relation. ne là khác nhau, eq là bằng nhau, lt là nhỏ hơn. Giữ tối đa 25 biến, 9 giá trị mỗi miền và 120 ràng buộc.</p><label>Dữ liệu JSON<textarea v-model="input" rows="10" spellcheck="false"/></label><button type="button" @click="apply">Dùng CSP</button><p v-if="error" role="alert">{{ error }}</p></details><SearchTraceCode name="backtrackingSteps" :phase="state.phase"/><SearchTraceCode v-if="state.phase==='propagate'" name="ac3Steps" :phase="state.propagation.phase"/></section></template>
<style scoped>
.csp-search{min-width:0}.csp-settings{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.csp-search label{display:grid;gap:6px;font:var(--fs-small)/1.7 var(--font-ui)}.csp-search :is(select,textarea,button){min-width:0;max-width:100%;min-height:44px;padding:8px;border:1px solid var(--control);border-radius:var(--radius);background:var(--paper);color:var(--ink);font:inherit}.csp-search textarea{font:13px/1.7 var(--font-code);width:100%}.csp-stats,.csp-queue{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}.csp-stats span,.csp-queue span{padding:6px;border:1px solid var(--rule);border-radius:var(--radius);font:var(--fs-small)/1.6 var(--font-ui)}.csp-queue h4{width:100%;font:600 var(--fs-small) var(--font-ui)}.csp-status{border-left:3px solid var(--tim);padding:12px;background:var(--tim-soft)}.choice-list p{font:var(--fs-small)/1.5 var(--font-ui);margin:8px 0}summary{min-height:44px;cursor:pointer}:is(select,textarea,button,summary):focus-visible{outline:3px solid var(--tim);outline-offset:3px}@media(max-width:480px){.csp-settings{grid-template-columns:1fr}}
</style>
